function period(kind){const now=new Date(),pad=n=>String(n).padStart(2,'0'),fmt=d=>d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());let from;if(kind==='week'){from=new Date(now);const day=(now.getDay()+6)%7;from.setDate(now.getDate()-day);$('rp-type').value='weekly'}else{from=new Date(now.getFullYear(),now.getMonth(),1);$('rp-type').value='monthly'}$('rp-from').value=fmt(from);$('rp-to').value=fmt(now);applyFilters()}
