$('rp-save').onclick=async()=>{try{const title=$('rp-title').value.trim()||((ar?'تقرير ':'Report ')+new Date().toLocaleDateString(ar?'ar-SA':'en-GB')),type=$('rp-type').value,payload=await snapshot(),j=await api('/api/reports',{method:'POST',body:JSON.stringify({title,report_type:type,payload})});const safe=title.replace(/[^a-z0-9_-]+/gi,'-').replace(/^-+|-+$/g,'')||'governance-report';download(safe+'.json','application/json;charset=utf-8',JSON.stringify({title,report_type:type,owner:user,created_at:j.report?.created_at||new Date().toISOString(),...payload},null,2));msg(ar?'تم حفظ التقرير وتحميل نسخة':'Report saved and downloaded');await list()}catch(e){msg((ar?'تعذر حفظ التقرير: ':'Could not save report: ')+(e.message||''))}};
const csvCell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';$('rp-csv').onclick=async()=>{const p=await snapshot(),latest={};p.evaluations.forEach(e=>{const k=String(e.employee_username||'').toLowerCase();if(!latest[k]||Number(e.id)>Number(latest[k].id))latest[k]=e});const rows=[['Date','Employee','Work Type','Quality','CSAT','Productivity','Employee Notes','Supervisor Evaluation','Supervisor Notes'],...p.records.map(r=>{const e=latest[empOf(r).toLowerCase()]||{};return[dateOf(r),empOf(r),r.service||'',r.quality??'',r.csat??'',r.prod??r.productivity??'',r.notes||'',e.score??'',e.notes||'']})],csv='\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),title=$('rp-title').value.trim()||'governance-report';download(title.replace(/[^a-z0-9_-]+/gi,'-')+'.csv','text/csv;charset=utf-8',csv);msg(ar?'تم تحميل CSV مع تقييم المشرف':'CSV downloaded with supervisor evaluation')};
function reportAnalytics(p){const rec=p.records||[],key=d=>{const s=dateOf(d),dt=new Date(s);if(isNaN(dt))return s||'Unknown';if(($('rp-type')?.value||'weekly')==='monthly')return dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0');const x=new Date(dt),day=(x.getDay()+6)%7;x.setDate(x.getDate()-day);return x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0')},groups={};rec.forEach(r=>{const k=key(r);(groups[k]||(groups[k]=[])).push(r)});const trend=Object.keys(groups).sort().map(k=>{const a=groups[k],av=x=>a.reduce((s,r)=>s+Number(r[x]||0),0)/a.length;return{period:k,quality:av('quality'),csat:av('csat'),productivity:a.reduce((s,r)=>s+Number(r.prod??r.productivity??0),0)}}),emps={};rec.forEach(r=>{const n=empOf(r)||'Unknown';(emps[n]||(emps[n]=[])).push(r)});const comparison=Object.entries(emps).map(([employee,a])=>({employee,quality:a.reduce((s,r)=>s+Number(r.quality||0),0)/a.length,csat:a.reduce((s,r)=>s+Number(r.csat||0),0)/a.length,productivity:a.reduce((s,r)=>s+Number(r.prod??r.productivity??0),0)})).sort((a,b)=>b.quality-a.quality),services={quality:0,tickets:0,surveys:0,other:0};rec.forEach(r=>{const k=String(r.service||'').toLowerCase();if(k in services)services[k]++;else services.other++});const target=90,meeting=rec.filter(r=>Number(r.quality||0)>=target).length,targetRate=rec.length?meeting/rec.length*100:0,top=comparison.slice(0,3),low=[...comparison].sort((a,b)=>a.quality-b.quality).slice(0,3);return{trend,comparison,services,target,targetRate,top,low}}
function executiveSummary(p,an){const rec=p.records||[],avg=k=>rec.length?rec.reduce((s,r)=>s+Number(r[k]||0),0)/rec.length:0,q=avg('quality'),cs=avg('csat'),prod=rec.reduce((s,r)=>s+Number(r.prod??r.productivity??0),0),last=an.trend[an.trend.length-1],prev=an.trend[an.trend.length-2],dq=last&&prev?last.quality-prev.quality:0,dc=last&&prev?last.csat-prev.csat:0,dp=last&&prev?last.productivity-prev.productivity:0,best=an.top[0],low=an.low[0],dominant=Object.entries(an.services).sort((a,b)=>b[1]-a[1])[0]||['other',0],svc={quality:ar?'جودة 909':'909 Quality',tickets:ar?'التذاكر الإلكترونية':'Electronic Tickets',surveys:ar?'استطلاعات العملاء':'Customer Surveys',other:ar?'أعمال أخرى':'Other Work'}[dominant[0]];let observations=[],recommendations=[];if(!rec.length)return{headline:ar?'لا توجد بيانات ضمن الفلاتر المحددة.':'No data is available for the selected filters.',observations:[],recommendations:[]};observations.push((ar?'متوسط الجودة ':'Average Quality is ')+q.toFixed(1)+'%'+(ar?' ومتوسط رضا العملاء ':' and average CSAT is ')+cs.toFixed(1)+'%.');observations.push((ar?'تم تحقيق مستهدف الجودة 90% في ':'The 90% quality target was achieved in ')+an.targetRate.toFixed(1)+'%'+(ar?' من السجلات.':' of records.'));observations.push((ar?'إجمالي الإنتاجية ':'Total productivity is ')+prod+(ar?' عبر ':' across ')+rec.length+(ar?' سجل.':' records.'));if(last&&prev)observations.push((ar?'مقارنة بالفترة السابقة: الجودة ':'Versus the previous period: Quality ')+(dq>=0?'+':'')+dq.toFixed(1)+(ar?' نقطة، CSAT ':' pts, CSAT ')+(dc>=0?'+':'')+dc.toFixed(1)+(ar?' نقطة، والإنتاجية ':' pts, Productivity ')+(dp>=0?'+':'')+dp.toFixed(0)+'.');if(best&&an.comparison.length>1)observations.push((ar?'أعلى أداء: ':'Top performer: ')+best.employee+' ('+best.quality.toFixed(1)+'% Quality).');if(low&&an.comparison.length>1)observations.push((ar?'الأداء الأقل: ':'Lowest performer: ')+low.employee+' ('+low.quality.toFixed(1)+'% Quality).');if(dominant[1])observations.push((ar?'أكبر حجم عمل كان في ':'Largest work volume was in ')+svc+' ('+(dominant[1]/rec.length*100).toFixed(1)+'%).');if(q<90)recommendations.push(ar?'رفع متوسط الجودة إلى 90% على الأقل من خلال مراجعة أسباب الأخطاء والسجلات الأقل أداءً.':'Raise average Quality to at least 90% by reviewing error causes and the lowest-performing records.');else recommendations.push(ar?'المحافظة على مستوى الجودة الحالي مع متابعة أي انخفاض أسبوعي أو شهري.':'Maintain the current Quality level and monitor any weekly or monthly decline.');if(cs<90)recommendations.push(ar?'إعطاء أولوية لإجراءات تحسين رضا العملاء ومراجعة الحالات ذات CSAT المنخفض.':'Prioritize customer-satisfaction actions and review cases with low CSAT.');if(last&&prev&&dq<0)recommendations.push(ar?'يوجد انخفاض في الجودة مقارنة بالفترة السابقة؛ يوصى بمراجعة السبب مع المشرف والفريق.':'Quality declined versus the previous period; review the cause with the supervisor and team.');if(last&&prev&&dp<0)recommendations.push(ar?'الإنتاجية انخفضت عن الفترة السابقة؛ راجع توزيع الأحمال وأسباب الانخفاض.':'Productivity declined versus the previous period; review workload distribution and causes.');if(low&&an.comparison.length>1)recommendations.push((ar?'إعداد خطة تحسين ومتابعة للموظف ':'Create an improvement and follow-up plan for ')+low.employee+'.');return{headline:(q>=90&&cs>=90?(ar?'الأداء العام قوي ويحقق المستهدف في الجودة ورضا العملاء.':'Overall performance is strong and meets Quality and CSAT targets.'):(q>=80&&cs>=80?(ar?'الأداء العام جيد مع وجود فرص واضحة للتحسين.':'Overall performance is good, with clear opportunities for improvement.'):(ar?'الأداء العام يحتاج إلى إجراءات تحسين ومتابعة.':'Overall performance requires improvement actions and follow-up.'))),observations,recommendations}}
function svgLineChart(data,title){if(!data.length)return'';const W=900,H=330,pad=55,x=i=>pad+(W-pad*2)*(data.length===1?.5:i/(data.length-1)),y=v=>H-pad-(H-pad*2)*Math.max(0,Math.min(100,v))/100,pts=k=>data.map((d,i)=>x(i)+','+y(Number(d[k]||0))).join(' '),labels=data.map((d,i)=>'<text x="'+x(i)+'" y="'+(H-18)+'" text-anchor="middle" font-size="11" fill="#555">'+String(d.period).slice(5)+'</text>').join('');return'<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'"><rect width="100%" height="100%" fill="white"/><text x="55" y="28" font-family="Arial" font-size="20" font-weight="bold" fill="#542080">'+title+'</text>'+[0,25,50,75,100].map(v=>'<line x1="55" y1="'+y(v)+'" x2="845" y2="'+y(v)+'" stroke="#e4e7eb"/><text x="45" y="'+(y(v)+4)+'" text-anchor="end" font-size="10">'+v+'%</text>').join('')+'<polyline fill="none" stroke="#542080" stroke-width="4" points="'+pts('quality')+'"/><polyline fill="none" stroke="#0C477F" stroke-width="4" points="'+pts('csat')+'"/>'+labels+'<text x="620" y="28" font-size="12" fill="#542080">Quality</text><text x="700" y="28" font-size="12" fill="#0C477F">CSAT</text></svg>'}
function svgBarChart(data,title){if(!data.length)return'';const W=900,H=360,pad=60,bw=Math.max(14,Math.min(55,(W-pad*2)/Math.max(1,data.length)/2.6)),step=(W-pad*2)/Math.max(1,data.length),y=v=>H-pad-(H-pad*2)*Math.max(0,Math.min(100,v))/100,bars=data.map((d,i)=>{const x=pad+i*step+step*.2;return'<rect x="'+x+'" y="'+y(d.quality)+'" width="'+bw+'" height="'+(H-pad-y(d.quality))+'" fill="#542080"/><rect x="'+(x+bw+4)+'" y="'+y(d.csat)+'" width="'+bw+'" height="'+(H-pad-y(d.csat))+'" fill="#0C477F"/><text x="'+(x+bw)+'" y="'+(H-24)+'" text-anchor="middle" font-size="10">'+String(d.employee).slice(0,15)+'</text>'}).join('');return'<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'"><rect width="100%" height="100%" fill="white"/><text x="60" y="28" font-family="Arial" font-size="20" font-weight="bold" fill="#542080">'+title+'</text>'+[0,25,50,75,100].map(v=>'<line x1="60" y1="'+y(v)+'" x2="840" y2="'+y(v)+'" stroke="#e4e7eb"/><text x="50" y="'+(y(v)+4)+'" text-anchor="end" font-size="10">'+v+'%</text>').join('')+bars+'<text x="650" y="28" font-size="12" fill="#542080">Quality</text><text x="730" y="28" font-size="12" fill="#0C477F">CSAT</text></svg>'}
