$('rp-upload').onclick=async()=>{const f=$('rp-file').files[0];if(!f){msg(ar?'اختر ملف JSON أو CSV أو TXT أولاً':'Choose a JSON, CSV, or TXT file first');return}if(f.size>700000){msg(ar?'حجم الملف كبير. الحد الحالي 700 KB':'File is too large. Current limit is 700 KB');return}try{const text=await f.text(),ext=(f.name.split('.').pop()||'').toLowerCase();let payload;if(ext==='json')payload=JSON.parse(text);else if(ext==='csv'||ext==='txt')payload={uploaded_file:{name:f.name,type:ext,content:text}};else throw new Error(ar?'نوع الملف غير مدعوم':'Unsupported file type');const title=$('rp-title').value.trim()||f.name.replace(/\.[^.]+$/,'');await api('/api/reports',{method:'POST',body:JSON.stringify({title,report_type:'uploaded_'+ext,payload})});$('rp-file').value='';msg(ar?'تم رفع التقرير وحفظه مركزيًا':'Report uploaded and saved centrally');await list()}catch(e){msg((ar?'تعذر رفع الملف: ':'Upload failed: ')+(e.message||''))}};
$('rp-refresh').onclick=async()=>{await loadBase();await list()};$('rp-body').onclick=async e=>{const id=e.target.dataset.down,del=e.target.dataset.rdel;if(id){try{const j=await api('/api/reports/'+id),r=j.report;download('governance-report-'+id+'.json','application/json;charset=utf-8',JSON.stringify({title:r.title,type:r.report_type,owner:r.owner_username,created_at:r.created_at,...r.payload},null,2))}catch(x){msg(ar?'تعذر تحميل التقرير':'Could not download report')}}if(del&&confirm(ar?'هل تريد حذف هذا التقرير؟':'Delete this report?')){try{await api('/api/reports/'+del,{method:'DELETE'});msg(ar?'تم حذف التقرير':'Report deleted');await list()}catch(x){msg(ar?'تعذر حذف التقرير':'Could not delete report')}}};
const openReports=()=>{document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));document.querySelectorAll('main .tab').forEach(x=>x.classList.remove('active'));b.hidden=false;b.style.display='';b.classList.add('active');s.hidden=false;s.style.display='';s.classList.add('active');s.scrollIntoView({behavior:'smooth',block:'start'});loadBase().catch(()=>{});list().catch(()=>{})};b.onclick=e=>{e.preventDefault();e.stopPropagation();openReports()};b.addEventListener('click',e=>{e.preventDefault();openReports()});window.__openGovernanceReports=openReports;loadBase();list();
